      const p = a + b - c, pa = Math.abs(p-a), pb = Math.abs(p-b), pc = Math.abs(p-c);
      val += (pa <= pb && pa <= pc) ? a : (pb <= pc ? b : c);
    }
    out[y*w*bpp + x] = val & 255;
  }
}
// average per column
const cols = [];
for (let x=0; x<w; x++) {
  let r=0,g=0,b=0;
  for (let y=0; y<h; y++) { const i=(y*w+x)*bpp; r+=out[i]; g+=out[i+1]; b+=out[i+2]; }
  cols.push([r/h|0, g/h|0, b/h|0]);
}
// print summary: group columns into 100 buckets of 10px, print avg
let line='';
for (let i=0; i<100; i++) {
  let r=0,g=0,b=0;
  for (let j=0;j<10;j++){ const c=cols[i*10+j]; r+=c[0]; g+=c[1]; b+=c[2]; }
  r/=10; g/=10; b/=10;
  line += `[${i}: ${(r|0)},${(g|0)},${(b|0)}] `;
}
return line;

