import sys
from PIL import Image
import colorsys

im = Image.open('barcode.png').convert('RGB')
w, h = im.size
px = im.load()

cols = []
for x in range(w):
    r = g = b = 0
    for y in range(h):
        p = px[x, y]
        r += p[0]; g += p[1]; b += p[2]
    cols.append((r / h, g / h, b / h))

def to_hex(c):
    return '#%02x%02x%02x' % (int(c[0]), int(c[1]), int(c[2]))

# Print compact 100-char summary: classify each column into a category
def classify(c):
    r, g, b = [v / 255.0 for v in c]
    h_, s, v = colorsys.rgb_to_hsv(r, g, b)
    if v < 0.12:
        return 'K'  # black
    if s < 0.15:
        if v > 0.75: return 'W'  # white/very light gray
        return 'G'  # gray
    hue = h_ * 360
    if s < 0.35:
        if v > 0.65:
            return 't'  # light tan/beige
        return 'd'  # dark tan/brown
    if 20 <= hue < 70:
        return 'O'  # orange/brown saturated
    if 70 <= hue < 160:
        return 'g'  # green/olive
    if 160 <= hue < 260:
        return 'B'  # blue/teal
    if hue >= 260 or hue < 15:
        if hue >= 330 or hue < 15:
            return 'R'  # red-ish
        return 'P'  # purple
    return '?'

groups = []
for x in range(w):
    k = classify(cols[x])
    if groups and groups[-1][0] == k:
        groups[-1][2] = x
    else:
        groups.append([k, x, x])

for k, a, b in groups:
    if b - a + 1 >= 3 or k in ('K', 'R', 'B', 'O', 'W'):
        avg = [0, 0, 0]
        n = b - a + 1
        for x in range(a, b + 1):
            for i in range(3):
                avg[i] += cols[x][i]
        avg = [v / n for v in avg]
        print(f"{k} x={a}-{b} (n={n}) avg={to_hex(avg)}")

print('--- 100-char classification string (each char = 10px) ---')
s = ''
for i in range(0, w, 10):
    # majority over 10 cols
    cnt = {}
    for j in range(i, i + 10):
        k = classify(cols[j])
        cnt[k] = cnt.get(k, 0) + 1
    s += max(cnt, key=cnt.get)
print(s)

print('--- bucket averages every 25px (40 buckets) ---')
for i in range(0, w, 25):
    r = g = b = 0
    n = min(25, w - i)
    for j in range(i, i + n):
        r += cols[j][0]; g += cols[j][1]; b += cols[j][2]
    print(i, to_hex((r / n, g / n, b / n)))

# overall luminance profile every 10px
print('--- luminance every 10px ---')
lum = []
for x in range(w):
    c = cols[x]
    lum.append(0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2])
print(' '.join(f"{int(max(0,min(99,l/2.55))):02d}" for l in lum[::10]))

